.why-feature-text h4 {
  margin-bottom: var(--space-1);
  font-size: 1rem;
}

.why-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Global Scale ===== */
.global-scale {
  background: var(--color-bg-alt);
}

.scale-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.scale-visual {
  position: relative;
}

.scale-globe {
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  background: radial-gradient(circle at 30% 30%, var(--color-accent-glow), transparent 60%),
              radial-gradient(circle, var(--color-bg-alt), var(--color-border-light));
  border-radius: 50%;
  margin: 0 auto;
  position: relative;
  border: 1px solid var(--color-border);
}

.scale-stats-inline {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  margin-top: var(--space-8);
}

.scale-stat-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.scale-stat-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.scale-stat-info h4 {
  font-size: 1.5rem;
  color: var(--color-primary);
  margin-bottom: 2px;
}

.scale-stat-info p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== AI Automations ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.ai-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.ai-feature-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.ai-feature-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-dark));
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.ai-feature-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.125rem;
}

.ai-feature-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Testimonials Carousel ===== */
.testimonials {
  background: var(--color-bg-alt);
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: var(--space-4);
}

.testimonial-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  max-width: 700px;
  margin: 0 auto;
}

.testimonial-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--color-burgundy);
  flex-shrink: 0;
}

.testimonial-name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  color: var(--color-primary);
}

.testimonial-role {
  font-size: 0.813rem;
  color: var(--color-text-light);
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--color-text);
  font-size: 1.25rem;
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-base);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--color-accent);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Pricing ===== */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  align-items: start;
}

.pricing-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.pricing-name {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
}

.pricing-description {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--space-1);
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: 0.875rem;
  color: var(--color-text);
}

.pricing-feature-check {
  width: 20px;
  height: 20px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-note {
  text-align: center;
  margin-top: var(--space-8);
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.pricing-note a {
  color: var(--color-burgundy);
  font-weight: 600;
  text-decoration: underline;
}

/* ===== Enterprise CTA ===== */
.enterprise-cta {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  margin-top: var(--space-10);
  text-align: center;
}

.enterprise-cta h3 {
  margin-bottom: var(--space-3);
}

.enterprise-cta p {
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--space-4);
}

.integration-item {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  transition: all var(--transition-fast);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text);
}

.integration-item:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.integration-item-icon {
  width: 32px;
  height: 32px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-burgundy);
}

/* ===== Social Proof / CTA Banner ===== */
.cta-banner {
  background: var(--color-primary);
  padding: var(--space-16) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-banner h2 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-4);
  position: relative;
}

.cta-banner p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1.125rem;
  margin-bottom: var(--space-8);
  position: relative;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-banner .btn {
  position: relative;
}

.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-10);
  margin-top: var(--space-12);
  flex-wrap: wrap;
}

.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.faq-item.active {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: all var(--transition-fast);
}

.faq-question:hover {
  background: var(--color-bg-alt);
}

.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all var(--transition-base);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-text-light);
}

.faq-item.active .faq-icon {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 var(--space-6) var(--space-5);
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.7;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-dark);
  color: rgba(255, 255, 255, 0.7);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  margin-top: var(--space-4);
  max-width: 280px;
}

.footer-column h4 {
  color: var(--color-text-inverse);
  font-size: 0.813rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-5);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-links a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-inverse);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.813rem;
}

.footer-bottom-links {
  display: flex;
  gap: var(--space-6);
}

.footer-bottom-links a {
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition-fast);
}

.footer-bottom-links a:hover {
  color: var(--color-accent);
}

/* ===== Page-specific: Online Courses ===== */
.engagement-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.engagement-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.engagement-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.engagement-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.engagement-card h3 {
  margin-bottom: var(--space-3);
}

.engagement-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* Product Demo Accordion */
.product-demo-section {
  background: var(--color-bg-alt);
}

.demo-accordion {
  max-width: 900px;
  margin: 0 auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-card);
  overflow: hidden;
}

.demo-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) var(--space-8);
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--transition-fast);
}

.demo-trigger:hover {
  background: var(--color-bg-alt);
}

.demo-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  font-size: 1rem;
  flex-shrink: 0;
}

.demo-accordion.active .demo-icon {
  transform: rotate(45deg);
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-text-inverse);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.demo-accordion.active .demo-content {
  max-height: 600px;
}

.demo-content-inner {
  padding: 0 var(--space-8) var(--space-8);
}

.demo-mockup {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  border: 1px solid var(--color-border-light);
  min-height: 200px;
}

.demo-mockup-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.demo-mockup-col {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.demo-mockup-block {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-sm);
  padding: var(--space-3);
  font-size: 0.813rem;
  color: var(--color-text-light);
}

/* Tools Grid */
.tools-grid-large {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-4);
}

.tool-tag {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: var(--space-2) var(--space-4);
  font-size: 0.813rem;
  font-weight: 500;
  color: var(--color-text);
  text-align: center;
  transition: all var(--transition-fast);
  cursor: default;
}

.tool-tag:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-glow);
}

.tool-category {
  margin-bottom: var(--space-10);
}

.tool-category h3 {
  font-size: 0.938rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-light);
  margin-bottom: var(--space-4);
}

/* ===== Page-specific: Digital Downloads ===== */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.value-prop-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.value-prop-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.value-prop-icon {
  width: 56px;
  height: 56px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
  color: var(--color-primary);
}

.value-prop-card h3 {
  margin-bottom: var(--space-3);
}

.value-prop-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-4);
}

.file-type-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  text-align: center;
  transition: all var(--transition-fast);
}

.file-type-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.file-type-icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
}

.file-type-card h4 {
  font-size: 0.938rem;
}

/* Create & Sell Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.step-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  transition: all var(--transition-base);
}

.step-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.step-number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-4);
  opacity: 0.3;
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Memberships ===== */
.membership-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.benefit-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.benefit-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.benefit-stat {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-burgundy);
  line-height: 1;
  margin-bottom: var(--space-3);
}

.benefit-card h3 {
  margin-bottom: var(--space-3);
}

.benefit-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.resource-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  cursor: pointer;
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.resource-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
}

.resource-card h3 {
  font-size: 1.063rem;
  margin-bottom: var(--space-3);
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Coaching ===== */
.coaching-steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.coaching-step {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  text-align: center;
  transition: all var(--transition-base);
}

.coaching-step:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.coaching-step-num {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--color-primary);
  margin: 0 auto var(--space-5);
}

.coaching-step h3 {
  margin-bottom: var(--space-3);
}

.coaching-step p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.coaching-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  display: flex;
  gap: var(--space-5);
  transition: all var(--transition-base);
}

.coaching-feature-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
}

.coaching-feature-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.coaching-feature-text h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.coaching-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.spotlight-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-avatar {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-4);
}

.spotlight-card h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.spotlight-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Animations ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-content {
    order: 1;
  }

  .hero-visual {
    order: 0;
  }

  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

  .hero-tabs {
    margin-left: auto;
    margin-right: auto;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ai-features-grid {
    grid-template-columns: 1fr;
  }

  .scale-grid {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .pricing-card.featured:hover {
    transform: translateY(-4px);
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .coaching-features-grid {
    grid-template-columns: 1fr;
  }

  .spotlight-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .nav-links {
    display: none;
  }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--space-6);
    gap: var(--space-4);
    box-shadow: var(--shadow-lg);
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .engagement-grid,
  .value-props-grid,
  .membership-benefits-grid,
  .resources-grid,
  .coaching-steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }
}

@media (max-width: 768px) {
  .products-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .why-tabs-nav {
    gap: var(--space-4);
  }

  .section {
    padding: var(--space-12) 0;
  }

  .why-features-grid {
    grid-template-columns: 1fr;
  }

  .tools-grid-large {
    grid-template-columns: repeat(2, 1fr);
  }

  .file-types-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .carousel-btn {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}

/* ===== Utility ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.bg-alt { background: var(--color-bg-alt); }
.bg-dark { background: var(--color-bg-dark); }
.bg-primary { background: var(--color-primary); }

.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }
