/* ===== LearnForge Design System ===== */
:root {
  /* Brand Colors */
  --color-primary: #000000;
  --color-primary-light: #1a1a1a;
  --color-accent: #E6FF32;
  --color-accent-dark: #c8e000;
  --color-accent-glow: rgba(230, 255, 50, 0.25);
  --color-burgundy: #7F2A23;
  --color-burgundy-light: #9a352b;

  /* Neutrals */
  --color-bg: #FFFFFF;
  --color-bg-alt: #F8FAFC;
  --color-bg-dark: #0a0a0a;
  --color-bg-card: #FFFFFF;
  --color-text: #1E293B;
  --color-text-light: #64748B;
  --color-text-inverse: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: #F1F5F9;

  /* Semantic */
  --color-success: #16A34A;
  --color-error: #DC2626;

  /* Typography */
  --font-heading: 'Poppins', 'Inter', sans-serif;
  --font-body: 'Open Sans', 'Inter', sans-serif;

  /* Spacing Scale (4pt) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.08), 0 2px 4px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.1), 0 4px 8px rgba(0, 0, 0, 0.04);
  --shadow-xl: 0 20px 48px rgba(0, 0, 0, 0.12), 0 8px 16px rgba(0, 0, 0, 0.04);

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* ===== Reset / Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-burgundy);
  margin-bottom: var(--space-3);
}

.section-title {
  margin-bottom: var(--space-4);
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-light);
  max-width: 640px;
  line-height: 1.7;
}

.text-center { text-align: center; }
.text-gradient {
  background: linear-gradient(135deg, var(--color-primary), var(--color-burgundy));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.section {
  padding: var(--space-20) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.section-header .section-subtitle {
  margin: 0 auto;
}

/* ===== Navigation ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  z-index: 1000;
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-family: var(--font-heading);
  font-size: 0.938rem;
  font-weight: 500;
  color: var(--color-text);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.nav-btn-secondary {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.nav-btn-secondary:hover {
  background: var(--color-bg-alt);
}

.nav-btn-primary {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-accent);
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.nav-btn-primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px var(--color-accent-glow);
}

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  cursor: pointer;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.nav-mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  padding: var(--space-4) var(--space-8);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px var(--color-accent-glow);
}

.btn-secondary {
  background: transparent;
  color: var(--color-text);
  border: 2px solid var(--color-border);
}

.btn-secondary:hover {
  border-color: var(--color-primary);
  background: var(--color-bg-alt);
}

.btn-dark {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.btn-dark:hover {
  background: var(--color-primary-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-burgundy {
  background: var(--color-burgundy);
  color: var(--color-text-inverse);
}

.btn-burgundy:hover {
  background: var(--color-burgundy-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-lg {
  font-size: 1.125rem;
  padding: var(--space-4) var(--space-10);
}

/* ===== Hero ===== */
.hero {
  padding: calc(var(--nav-height) + var(--space-16)) 0 var(--space-20);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-title {
  margin-bottom: var(--space-6);
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-light);
  line-height: 1.7;
  margin-bottom: var(--space-8);
  max-width: 520px;
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

/* Hero Tab Switch (Homepage) */
.hero-tabs {
  display: flex;
  gap: var(--space-1);
  background: var(--color-bg-alt);
  padding: var(--space-1);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-6);
  width: fit-content;
  border: 1px solid var(--color-border);
}

.hero-tab {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  color: var(--color-text-light);
}

.hero-tab.active {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  box-shadow: var(--shadow-md);
}

.hero-preview {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  position: relative;
}

.hero-preview-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
}

.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
}

.hero-preview-dot:nth-child(1) { background: #EF4444; }
.hero-preview-dot:nth-child(2) { background: #F59E0B; }
.hero-preview-dot:nth-child(3) { background: #10B981; }

.hero-preview-body {
  padding: var(--space-6);
  min-height: 300px;
}

.hero-preview-inner {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-4);
  height: 100%;
}

.hero-preview-sidebar {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.hero-preview-sidebar-item {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--color-text-light);
}

.hero-preview-sidebar-item.active {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.hero-preview-main {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.hero-preview-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  border: 1px solid var(--color-border-light);
}

.hero-preview-card-bar {
  height: 8px;
  background: var(--color-border);
  border-radius: var(--radius-full);
  width: 60%;
  margin-bottom: var(--space-2);
}

.hero-preview-card-bar.short { width: 40%; }

.hero-preview-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
  margin-top: var(--space-3);
}

.hero-preview-stat {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  text-align: center;
}

.hero-preview-stat-value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}

.hero-preview-stat-label {
  font-size: 0.688rem;
  color: var(--color-text-light);
  margin-top: 2px;
}

#preview-student {
  display: none;
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-primary);
  padding: var(--space-10) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  text-align: center;
}

.stat-item {
  padding: var(--space-4);
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3vw, 2.75rem);
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-label {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1rem;
}

/* ===== Products Grid ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.product-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8) var(--space-6);
  transition: all var(--transition-base);
  text-align: center;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
}

.product-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.25rem;
}

.product-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.6;
}

/* ===== Why Choose Us (Tabs) ===== */
.why-tabs-nav {
  display: flex;
  gap: var(--space-6);
  border-bottom: 2px solid var(--color-border);
  margin-bottom: var(--space-10);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.why-tab-btn {
  font-family: var(--font-heading);
  font-size: 0.938rem;
  font-weight: 600;
  color: var(--color-text-light);
  padding: 0 0 var(--space-4);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition-base);
  white-space: nowrap;
}

.why-tab-btn:hover {
  color: var(--color-text);
}

.why-tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-accent);
}

.why-tab-content {
  display: none;
}

.why-tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
}

.why-feature-item {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1rem;
  color: var(--color-primary);
  font-weight: 700;
}

.why-feature-text h4 {
  margin-bottom: var(--space-1);
  font-size: 1rem;
}

.why-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Global Scale ===== */
.global-scale {
  background: var(--color-bg-alt);
}

.scale-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.scale-visual {
  position: relative;
}

.scale-globe {
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  background: radial-gradient(circle at 30% 30%, var(--color-accent-glow), transparent 60%),
              radial-gradient(circle, var(--color-bg-alt), var(--color-border-light));
  border-radius: 50%;
  margin: 0 auto;
  position: relative;
  border: 1px solid var(--color-border);
}

.scale-stats-inline {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  margin-top: var(--space-8);
}

.scale-stat-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.scale-stat-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.scale-stat-info h4 {
  font-size: 1.5rem;
  color: var(--color-primary);
  margin-bottom: 2px;
}

.scale-stat-info p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== AI Automations ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.ai-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.ai-feature-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.ai-feature-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-dark));
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.ai-feature-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.125rem;
}

.ai-feature-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Testimonials Carousel ===== */
.testimonials {
  background: var(--color-bg-alt);
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: var(--space-4);
}

.testimonial-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  max-width: 700px;
  margin: 0 auto;
}

.testimonial-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--color-burgundy);
  flex-shrink: 0;
}

.testimonial-name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  color: var(--color-primary);
}

.testimonial-role {
  font-size: 0.813rem;
  color: var(--color-text-light);
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--color-text);
  font-size: 1.25rem;
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-base);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--color-accent);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Pricing ===== */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  align-items: start;
}

.pricing-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.pricing-name {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
}

.pricing-description {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--space-1);
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: 0.875rem;
  color: var(--color-text);
}

.pricing-feature-check {
  width: 20px;
  height: 20px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-note {
  text-align: center;
  margin-top: var(--space-8);
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.pricing-note a {
  color: var(--color-burgundy);
  font-weight: 600;
  text-decoration: underline;
}

/* ===== Enterprise CTA ===== */
.enterprise-cta {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  margin-top: var(--space-10);
  text-align: center;
}

.enterprise-cta h3 {
  margin-bottom: var(--space-3);
}

.enterprise-cta p {
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--space-4);
}

.integration-item {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  transition: all var(--transition-fast);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text);
}

.integration-item:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.integration-item-icon {
  width: 32px;
  height: 32px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-burgundy);
}

/* ===== Social Proof / CTA Banner ===== */
.cta-banner {
  background: var(--color-primary);
  padding: var(--space-16) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-banner h2 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-4);
  position: relative;
}

.cta-banner p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1.125rem;
  margin-bottom: var(--space-8);
  position: relative;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-banner .btn {
  position: relative;
}

.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-10);
  margin-top: var(--space-12);
  flex-wrap: wrap;
}

.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.faq-item.active {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: all var(--transition-fast);
}

.faq-question:hover {
  background: var(--color-bg-alt);
}

.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all var(--transition-base);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-text-light);
}

.faq-item.active .faq-icon {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 var(--space-6) var(--space-5);
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.7;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-dark);
  color: rgba(255, 255, 255, 0.7);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  margin-top: var(--space-4);
  max-width: 280px;
}

.footer-column h4 {
  color: var(--color-text-inverse);
  font-size: 0.813rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-5);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-links a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-inverse);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.813rem;
}

.footer-bottom-links {
  display: flex;
  gap: var(--space-6);
}

.footer-bottom-links a {
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition-fast);
}

.footer-bottom-links a:hover {
  color: var(--color-accent);
}

/* ===== Page-specific: Online Courses ===== */
.engagement-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.engagement-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.engagement-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.engagement-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.engagement-card h3 {
  margin-bottom: var(--space-3);
}

.engagement-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* Product Demo Accordion */
.product-demo-section {
  background: var(--color-bg-alt);
}

.demo-accordion {
  max-width: 900px;
  margin: 0 auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-card);
  overflow: hidden;
}

.demo-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) var(--space-8);
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--transition-fast);
}

.demo-trigger:hover {
  background: var(--color-bg-alt);
}

.demo-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  font-size: 1rem;
  flex-shrink: 0;
}

.demo-accordion.active .demo-icon {
  transform: rotate(45deg);
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-text-inverse);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.demo-accordion.active .demo-content {
  max-height: 600px;
}

.demo-content-inner {
  padding: 0 var(--space-8) var(--space-8);
}

.demo-mockup {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  border: 1px solid var(--color-border-light);
  min-height: 200px;
}

.demo-mockup-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.demo-mockup-col {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.demo-mockup-block {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-sm);
  padding: var(--space-3);
  font-size: 0.813rem;
  color: var(--color-text-light);
}

/* Tools Grid */
.tools-grid-large {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-4);
}

.tool-tag {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: var(--space-2) var(--space-4);
  font-size: 0.813rem;
  font-weight: 500;
  color: var(--color-text);
  text-align: center;
  transition: all var(--transition-fast);
  cursor: default;
}

.tool-tag:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-glow);
}

.tool-category {
  margin-bottom: var(--space-10);
}

.tool-category h3 {
  font-size: 0.938rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-light);
  margin-bottom: var(--space-4);
}

/* ===== Page-specific: Digital Downloads ===== */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.value-prop-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.value-prop-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.value-prop-icon {
  width: 56px;
  height: 56px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
  color: var(--color-primary);
}

.value-prop-card h3 {
  margin-bottom: var(--space-3);
}

.value-prop-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-4);
}

.file-type-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  text-align: center;
  transition: all var(--transition-fast);
}

.file-type-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.file-type-icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
}

.file-type-card h4 {
  font-size: 0.938rem;
}

/* Create & Sell Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.step-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  transition: all var(--transition-base);
}

.step-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.step-number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-4);
  opacity: 0.3;
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Memberships ===== */
.membership-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.benefit-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.benefit-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.benefit-stat {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-burgundy);
  line-height: 1;
  margin-bottom: var(--space-3);
}

.benefit-card h3 {
  margin-bottom: var(--space-3);
}

.benefit-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.resource-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  cursor: pointer;
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.resource-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
}

.resource-card h3 {
  font-size: 1.063rem;
  margin-bottom: var(--space-3);
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Coaching ===== */
.coaching-steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.coaching-step {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  text-align: center;
  transition: all var(--transition-base);
}

.coaching-step:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.coaching-step-num {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--color-primary);
  margin: 0 auto var(--space-5);
}

.coaching-step h3 {
  margin-bottom: var(--space-3);
}

.coaching-step p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.coaching-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  display: flex;
  gap: var(--space-5);
  transition: all var(--transition-base);
}

.coaching-feature-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
}

.coaching-feature-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.coaching-feature-text h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.coaching-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.spotlight-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-avatar {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-4);
}

.spotlight-card h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.spotlight-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Animations ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-content {
    order: 1;
  }

  .hero-visual {
    order: 0;
  }

  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

  .hero-tabs {
    margin-left: auto;
    margin-right: auto;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ai-features-grid {
    grid-template-columns: 1fr;
  }

  .scale-grid {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .pricing-card.featured:hover {
    transform: translateY(-4px);
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .coaching-features-grid {
    grid-template-columns: 1fr;
  }

  .spotlight-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .nav-links {
    display: none;
  }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--space-6);
    gap: var(--space-4);
    box-shadow: var(--shadow-lg);
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .engagement-grid,
  .value-props-grid,
  .membership-benefits-grid,
  .resources-grid,
  .coaching-steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }
}

@media (max-width: 768px) {
  .products-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .why-tabs-nav {
    gap: var(--space-4);
  }

  .section {
    padding: var(--space-12) 0;
  }

  .why-features-grid {
    grid-template-columns: 1fr;
  }

  .tools-grid-large {
    grid-template-columns: repeat(2, 1fr);
  }

  .file-types-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .carousel-btn {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}

/* ===== Utility ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.bg-alt { background: var(--color-bg-alt); }
.bg-dark { background: var(--color-bg-dark); }
.bg-primary { background: var(--color-primary); }

.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }

/* ===== LearnForge Design System ===== */
:root {
  /* Brand Colors */
  --color-primary: #000000;
  --color-primary-light: #1a1a1a;
  --color-accent: #E6FF32;
  --color-accent-dark: #c8e000;
  --color-accent-glow: rgba(230, 255, 50, 0.25);
  --color-burgundy: #7F2A23;
  --color-burgundy-light: #9a352b;

  /* Neutrals */
  --color-bg: #FFFFFF;
  --color-bg-alt: #F8FAFC;
  --color-bg-dark: #0a0a0a;
  --color-bg-card: #FFFFFF;
  --color-text: #1E293B;
  --color-text-light: #64748B;
  --color-text-inverse: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: #F1F5F9;

  /* Semantic */
  --color-success: #16A34A;
  --color-error: #DC2626;

  /* Typography */
  --font-heading: 'Poppins', 'Inter', sans-serif;
  --font-body: 'Open Sans', 'Inter', sans-serif;

  /* Spacing Scale (4pt) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.08), 0 2px 4px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.1), 0 4px 8px rgba(0, 0, 0, 0.04);
  --shadow-xl: 0 20px 48px rgba(0, 0, 0, 0.12), 0 8px 16px rgba(0, 0, 0, 0.04);

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* ===== Reset / Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-burgundy);
  margin-bottom: var(--space-3);
}

.section-title {
  margin-bottom: var(--space-4);
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-light);
  max-width: 640px;
  line-height: 1.7;
}

.text-center { text-align: center; }
.text-gradient {
  background: linear-gradient(135deg, var(--color-primary), var(--color-burgundy));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.section {
  padding: var(--space-20) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.section-header .section-subtitle {
  margin: 0 auto;
}

/* ===== Navigation ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  z-index: 1000;
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-family: var(--font-heading);
  font-size: 0.938rem;
  font-weight: 500;
  color: var(--color-text);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.nav-btn-secondary {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.nav-btn-secondary:hover {
  background: var(--color-bg-alt);
}

.nav-btn-primary {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-accent);
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.nav-btn-primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px var(--color-accent-glow);
}

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  cursor: pointer;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.nav-mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  padding: var(--space-4) var(--space-8);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px var(--color-accent-glow);
}

.btn-secondary {
  background: transparent;
  color: var(--color-text);
  border: 2px solid var(--color-border);
}

.btn-secondary:hover {
  border-color: var(--color-primary);
  background: var(--color-bg-alt);
}

.btn-dark {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.btn-dark:hover {
  background: var(--color-primary-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-burgundy {
  background: var(--color-burgundy);
  color: var(--color-text-inverse);
}

.btn-burgundy:hover {
  background: var(--color-burgundy-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-lg {
  font-size: 1.125rem;
  padding: var(--space-4) var(--space-10);
}

/* ===== Hero ===== */
.hero {
  padding: calc(var(--nav-height) + var(--space-16)) 0 var(--space-20);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-title {
  margin-bottom: var(--space-6);
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-light);
  line-height: 1.7;
  margin-bottom: var(--space-8);
  max-width: 520px;
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

/* Hero Tab Switch (Homepage) */
.hero-tabs {
  display: flex;
  gap: var(--space-1);
  background: var(--color-bg-alt);
  padding: var(--space-1);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-6);
  width: fit-content;
  border: 1px solid var(--color-border);
}

.hero-tab {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  color: var(--color-text-light);
}

.hero-tab.active {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  box-shadow: var(--shadow-md);
}

.hero-preview {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  position: relative;
}

.hero-preview-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
}

.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
}

.hero-preview-dot:nth-child(1) { background: #EF4444; }
.hero-preview-dot:nth-child(2) { background: #F59E0B; }
.hero-preview-dot:nth-child(3) { background: #10B981; }

.hero-preview-body {
  padding: var(--space-6);
  min-height: 300px;
}

.hero-preview-inner {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-4);
  height: 100%;
}

.hero-preview-sidebar {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.hero-preview-sidebar-item {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--color-text-light);
}

.hero-preview-sidebar-item.active {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.hero-preview-main {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.hero-preview-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  border: 1px solid var(--color-border-light);
}

.hero-preview-card-bar {
  height: 8px;
  background: var(--color-border);
  border-radius: var(--radius-full);
  width: 60%;
  margin-bottom: var(--space-2);
}

.hero-preview-card-bar.short { width: 40%; }

.hero-preview-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
  margin-top: var(--space-3);
}

.hero-preview-stat {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  text-align: center;
}

.hero-preview-stat-value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}

.hero-preview-stat-label {
  font-size: 0.688rem;
  color: var(--color-text-light);
  margin-top: 2px;
}

#preview-student {
  display: none;
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-primary);
  padding: var(--space-10) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  text-align: center;
}

.stat-item {
  padding: var(--space-4);
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3vw, 2.75rem);
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-label {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1rem;
}

/* ===== Products Grid ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.product-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8) var(--space-6);
  transition: all var(--transition-base);
  text-align: center;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
}

.product-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.25rem;
}

.product-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.6;
}

/* ===== Why Choose Us (Tabs) ===== */
.why-tabs-nav {
  display: flex;
  gap: var(--space-6);
  border-bottom: 2px solid var(--color-border);
  margin-bottom: var(--space-10);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.why-tab-btn {
  font-family: var(--font-heading);
  font-size: 0.938rem;
  font-weight: 600;
  color: var(--color-text-light);
  padding: 0 0 var(--space-4);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition-base);
  white-space: nowrap;
}

.why-tab-btn:hover {
  color: var(--color-text);
}

.why-tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-accent);
}

.why-tab-content {
  display: none;
}

.why-tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
}

.why-feature-item {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1rem;
  color: var(--color-primary);
  font-weight: 700;
}

.why-feature-text h4 {
  margin-bottom: var(--space-1);
  font-size: 1rem;
}

.why-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Global Scale ===== */
.global-scale {
  background: var(--color-bg-alt);
}

.scale-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.scale-visual {
  position: relative;
}

.scale-globe {
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  background: radial-gradient(circle at 30% 30%, var(--color-accent-glow), transparent 60%),
              radial-gradient(circle, var(--color-bg-alt), var(--color-border-light));
  border-radius: 50%;
  margin: 0 auto;
  position: relative;
  border: 1px solid var(--color-border);
}

.scale-stats-inline {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  margin-top: var(--space-8);
}

.scale-stat-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.scale-stat-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.scale-stat-info h4 {
  font-size: 1.5rem;
  color: var(--color-primary);
  margin-bottom: 2px;
}

.scale-stat-info p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== AI Automations ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.ai-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.ai-feature-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.ai-feature-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-dark));
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.ai-feature-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.125rem;
}

.ai-feature-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Testimonials Carousel ===== */
.testimonials {
  background: var(--color-bg-alt);
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: var(--space-4);
}

.testimonial-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  max-width: 700px;
  margin: 0 auto;
}

.testimonial-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--color-burgundy);
  flex-shrink: 0;
}

.testimonial-name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  color: var(--color-primary);
}

.testimonial-role {
  font-size: 0.813rem;
  color: var(--color-text-light);
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--color-text);
  font-size: 1.25rem;
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-base);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--color-accent);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Pricing ===== */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  align-items: start;
}

.pricing-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.pricing-name {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
}

.pricing-description {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--space-1);
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: 0.875rem;
  color: var(--color-text);
}

.pricing-feature-check {
  width: 20px;
  height: 20px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-note {
  text-align: center;
  margin-top: var(--space-8);
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.pricing-note a {
  color: var(--color-burgundy);
  font-weight: 600;
  text-decoration: underline;
}

/* ===== Enterprise CTA ===== */
.enterprise-cta {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  margin-top: var(--space-10);
  text-align: center;
}

.enterprise-cta h3 {
  margin-bottom: var(--space-3);
}

.enterprise-cta p {
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--space-4);
}

.integration-item {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  transition: all var(--transition-fast);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text);
}

.integration-item:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.integration-item-icon {
  width: 32px;
  height: 32px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-burgundy);
}

/* ===== Social Proof / CTA Banner ===== */
.cta-banner {
  background: var(--color-primary);
  padding: var(--space-16) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-banner h2 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-4);
  position: relative;
}

.cta-banner p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1.125rem;
  margin-bottom: var(--space-8);
  position: relative;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-banner .btn {
  position: relative;
}

.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-10);
  margin-top: var(--space-12);
  flex-wrap: wrap;
}

.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.faq-item.active {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: all var(--transition-fast);
}

.faq-question:hover {
  background: var(--color-bg-alt);
}

.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all var(--transition-base);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-text-light);
}

.faq-item.active .faq-icon {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 var(--space-6) var(--space-5);
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.7;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-dark);
  color: rgba(255, 255, 255, 0.7);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  margin-top: var(--space-4);
  max-width: 280px;
}

.footer-column h4 {
  color: var(--color-text-inverse);
  font-size: 0.813rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-5);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-links a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-inverse);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.813rem;
}

.footer-bottom-links {
  display: flex;
  gap: var(--space-6);
}

.footer-bottom-links a {
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition-fast);
}

.footer-bottom-links a:hover {
  color: var(--color-accent);
}

/* ===== Page-specific: Online Courses ===== */
.engagement-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.engagement-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.engagement-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.engagement-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.engagement-card h3 {
  margin-bottom: var(--space-3);
}

.engagement-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* Product Demo Accordion */
.product-demo-section {
  background: var(--color-bg-alt);
}

.demo-accordion {
  max-width: 900px;
  margin: 0 auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-card);
  overflow: hidden;
}

.demo-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) var(--space-8);
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--transition-fast);
}

.demo-trigger:hover {
  background: var(--color-bg-alt);
}

.demo-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  font-size: 1rem;
  flex-shrink: 0;
}

.demo-accordion.active .demo-icon {
  transform: rotate(45deg);
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-text-inverse);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.demo-accordion.active .demo-content {
  max-height: 600px;
}

.demo-content-inner {
  padding: 0 var(--space-8) var(--space-8);
}

.demo-mockup {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  border: 1px solid var(--color-border-light);
  min-height: 200px;
}

.demo-mockup-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.demo-mockup-col {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.demo-mockup-block {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-sm);
  padding: var(--space-3);
  font-size: 0.813rem;
  color: var(--color-text-light);
}

/* Tools Grid */
.tools-grid-large {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-4);
}

.tool-tag {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: var(--space-2) var(--space-4);
  font-size: 0.813rem;
  font-weight: 500;
  color: var(--color-text);
  text-align: center;
  transition: all var(--transition-fast);
  cursor: default;
}

.tool-tag:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-glow);
}

.tool-category {
  margin-bottom: var(--space-10);
}

.tool-category h3 {
  font-size: 0.938rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-light);
  margin-bottom: var(--space-4);
}

/* ===== Page-specific: Digital Downloads ===== */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.value-prop-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.value-prop-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.value-prop-icon {
  width: 56px;
  height: 56px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
  color: var(--color-primary);
}

.value-prop-card h3 {
  margin-bottom: var(--space-3);
}

.value-prop-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-4);
}

.file-type-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  text-align: center;
  transition: all var(--transition-fast);
}

.file-type-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.file-type-icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
}

.file-type-card h4 {
  font-size: 0.938rem;
}

/* Create & Sell Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.step-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  transition: all var(--transition-base);
}

.step-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.step-number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-4);
  opacity: 0.3;
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Memberships ===== */
.membership-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.benefit-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.benefit-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.benefit-stat {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-burgundy);
  line-height: 1;
  margin-bottom: var(--space-3);
}

.benefit-card h3 {
  margin-bottom: var(--space-3);
}

.benefit-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.resource-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  cursor: pointer;
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.resource-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
}

.resource-card h3 {
  font-size: 1.063rem;
  margin-bottom: var(--space-3);
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Coaching ===== */
.coaching-steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.coaching-step {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  text-align: center;
  transition: all var(--transition-base);
}

.coaching-step:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.coaching-step-num {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--color-primary);
  margin: 0 auto var(--space-5);
}

.coaching-step h3 {
  margin-bottom: var(--space-3);
}

.coaching-step p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.coaching-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  display: flex;
  gap: var(--space-5);
  transition: all var(--transition-base);
}

.coaching-feature-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
}

.coaching-feature-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.coaching-feature-text h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.coaching-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.spotlight-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-avatar {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-4);
}

.spotlight-card h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.spotlight-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Animations ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-content {
    order: 1;
  }

  .hero-visual {
    order: 0;
  }

  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

  .hero-tabs {
    margin-left: auto;
    margin-right: auto;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ai-features-grid {
    grid-template-columns: 1fr;
  }

  .scale-grid {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .pricing-card.featured:hover {
    transform: translateY(-4px);
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .coaching-features-grid {
    grid-template-columns: 1fr;
  }

  .spotlight-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .nav-links {
    display: none;
  }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--space-6);
    gap: var(--space-4);
    box-shadow: var(--shadow-lg);
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .engagement-grid,
  .value-props-grid,
  .membership-benefits-grid,
  .resources-grid,
  .coaching-steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }
}

@media (max-width: 768px) {
  .products-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .why-tabs-nav {
    gap: var(--space-4);
  }

  .section {
    padding: var(--space-12) 0;
  }

  .why-features-grid {
    grid-template-columns: 1fr;
  }

  .tools-grid-large {
    grid-template-columns: repeat(2, 1fr);
  }

  .file-types-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .carousel-btn {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}

/* ===== Utility ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.bg-alt { background: var(--color-bg-alt); }
.bg-dark { background: var(--color-bg-dark); }
.bg-primary { background: var(--color-primary); }

.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }

raw_arguments.content:
/* ===== LearnForge Design System ===== */
:root {
  /* Brand Colors */
  --color-primary: #000000;
  --color-primary-light: #1a1a1a;
  --color-accent: #E6FF32;
  --color-accent-dark: #c8e000;
  --color-accent-glow: rgba(230, 255, 50, 0.25);
  --color-burgundy: #7F2A23;
  --color-burgundy-light: #9a352b;

  /* Neutrals */
  --color-bg: #FFFFFF;
  --color-bg-alt: #F8FAFC;
  --color-bg-dark: #0a0a0a;
  --color-bg-card: #FFFFFF;
  --color-text: #1E293B;
  --color-text-light: #64748B;
  --color-text-inverse: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: #F1F5F9;

  /* Semantic */
  --color-success: #16A34A;
  --color-error: #DC2626;

  /* Typography */
  --font-heading: 'Poppins', 'Inter', sans-serif;
  --font-body: 'Open Sans', 'Inter', sans-serif;

  /* Spacing Scale (4pt) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.08), 0 2px 4px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.1), 0 4px 8px rgba(0, 0, 0, 0.04);
  --shadow-xl: 0 20px 48px rgba(0, 0, 0, 0.12), 0 8px 16px rgba(0, 0, 0, 0.04);

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* ===== Reset / Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-burgundy);
  margin-bottom: var(--space-3);
}

.section-title {
  margin-bottom: var(--space-4);
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-light);
  max-width: 640px;
  line-height: 1.7;
}

.text-center { text-align: center; }
.text-gradient {
  background: linear-gradient(135deg, var(--color-primary), var(--color-burgundy));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.section {
  padding: var(--space-20) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.section-header .section-subtitle {
  margin: 0 auto;
}

/* ===== Navigation ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  z-index: 1000;
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-family: var(--font-heading);
  font-size: 0.938rem;
  font-weight: 500;
  color: var(--color-text);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.nav-btn-secondary {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.nav-btn-secondary:hover {
  background: var(--color-bg-alt);
}

.nav-btn-primary {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-accent);
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.nav-btn-primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px var(--color-accent-glow);
}

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  cursor: pointer;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.nav-mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  padding: var(--space-4) var(--space-8);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px var(--color-accent-glow);
}

.btn-secondary {
  background: transparent;
  color: var(--color-text);
  border: 2px solid var(--color-border);
}

.btn-secondary:hover {
  border-color: var(--color-primary);
  background: var(--color-bg-alt);
}

.btn-dark {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.btn-dark:hover {
  background: var(--color-primary-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-burgundy {
  background: var(--color-burgundy);
  color: var(--color-text-inverse);
}

.btn-burgundy:hover {
  background: var(--color-burgundy-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-lg {
  font-size: 1.125rem;
  padding: var(--space-4) var(--space-10);
}

/* ===== Hero ===== */
.hero {
  padding: calc(var(--nav-height) + var(--space-16)) 0 var(--space-20);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-title {
  margin-bottom: var(--space-6);
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-light);
  line-height: 1.7;
  margin-bottom: var(--space-8);
  max-width: 520px;
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

/* Hero Tab Switch (Homepage) */
.hero-tabs {
  display: flex;
  gap: var(--space-1);
  background: var(--color-bg-alt);
  padding: var(--space-1);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-6);
  width: fit-content;
  border: 1px solid var(--color-border);
}

.hero-tab {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  color: var(--color-text-light);
}

.hero-tab.active {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  box-shadow: var(--shadow-md);
}

.hero-preview {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  position: relative;
}

.hero-preview-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
}

.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
}

.hero-preview-dot:nth-child(1) { background: #EF4444; }
.hero-preview-dot:nth-child(2) { background: #F59E0B; }
.hero-preview-dot:nth-child(3) { background: #10B981; }

.hero-preview-body {
  padding: var(--space-6);
  min-height: 300px;
}

.hero-preview-inner {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-4);
  height: 100%;
}

.hero-preview-sidebar {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.hero-preview-sidebar-item {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--color-text-light);
}

.hero-preview-sidebar-item.active {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.hero-preview-main {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.hero-preview-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  border: 1px solid var(--color-border-light);
}

.hero-preview-card-bar {
  height: 8px;
  background: var(--color-border);
  border-radius: var(--radius-full);
  width: 60%;
  margin-bottom: var(--space-2);
}

.hero-preview-card-bar.short { width: 40%; }

.hero-preview-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
  margin-top: var(--space-3);
}

.hero-preview-stat {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  text-align: center;
}

.hero-preview-stat-value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}

.hero-preview-stat-label {
  font-size: 0.688rem;
  color: var(--color-text-light);
  margin-top: 2px;
}

#preview-student {
  display: none;
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-primary);
  padding: var(--space-10) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  text-align: center;
}

.stat-item {
  padding: var(--space-4);
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3vw, 2.75rem);
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-label {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1rem;
}

/* ===== Products Grid ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.product-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8) var(--space-6);
  transition: all var(--transition-base);
  text-align: center;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
}

.product-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.25rem;
}

.product-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.6;
}

/* ===== Why Choose Us (Tabs) ===== */
.why-tabs-nav {
  display: flex;
  gap: var(--space-6);
  border-bottom: 2px solid var(--color-border);
  margin-bottom: var(--space-10);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.why-tab-btn {
  font-family: var(--font-heading);
  font-size: 0.938rem;
  font-weight: 600;
  color: var(--color-text-light);
  padding: 0 0 var(--space-4);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition-base);
  white-space: nowrap;
}

.why-tab-btn:hover {
  color: var(--color-text);
}

.why-tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-accent);
}

.why-tab-content {
  display: none;
}

.why-tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
}

.why-feature-item {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1rem;
  color: var(--color-primary);
  font-weight: 700;
}

.why-feature-text h4 {
  margin-bottom: var(--space-1);
  font-size: 1rem;
}

.why-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Global Scale ===== */
.global-scale {
  background: var(--color-bg-alt);
}

.scale-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.scale-visual {
  position: relative;
}

.scale-globe {
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  background: radial-gradient(circle at 30% 30%, var(--color-accent-glow), transparent 60%),
              radial-gradient(circle, var(--color-bg-alt), var(--color-border-light));
  border-radius: 50%;
  margin: 0 auto;
  position: relative;
  border: 1px solid var(--color-border);
}

.scale-stats-inline {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  margin-top: var(--space-8);
}

.scale-stat-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.scale-stat-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.scale-stat-info h4 {
  font-size: 1.5rem;
  color: var(--color-primary);
  margin-bottom: 2px;
}

.scale-stat-info p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== AI Automations ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.ai-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.ai-feature-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.ai-feature-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-dark));
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.ai-feature-card h3 {
  margin-bottom: var(--space-3);
  font-size: 1.125rem;
}

.ai-feature-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Testimonials Carousel ===== */
.testimonials {
  background: var(--color-bg-alt);
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: var(--space-4);
}

.testimonial-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  max-width: 700px;
  margin: 0 auto;
}

.testimonial-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--color-burgundy);
  flex-shrink: 0;
}

.testimonial-name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  color: var(--color-primary);
}

.testimonial-role {
  font-size: 0.813rem;
  color: var(--color-text-light);
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--color-text);
  font-size: 1.25rem;
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-base);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--color-accent);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Pricing ===== */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  align-items: start;
}

.pricing-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--color-accent);
  color: var(--color-primary);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.pricing-name {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
}

.pricing-description {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--space-1);
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: 0.875rem;
  color: var(--color-text);
}

.pricing-feature-check {
  width: 20px;
  height: 20px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-note {
  text-align: center;
  margin-top: var(--space-8);
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.pricing-note a {
  color: var(--color-burgundy);
  font-weight: 600;
  text-decoration: underline;
}

/* ===== Enterprise CTA ===== */
.enterprise-cta {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  margin-top: var(--space-10);
  text-align: center;
}

.enterprise-cta h3 {
  margin-bottom: var(--space-3);
}

.enterprise-cta p {
  color: var(--color-text-light);
  margin-bottom: var(--space-6);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--space-4);
}

.integration-item {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  transition: all var(--transition-fast);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text);
}

.integration-item:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.integration-item-icon {
  width: 32px;
  height: 32px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-burgundy);
}

/* ===== Social Proof / CTA Banner ===== */
.cta-banner {
  background: var(--color-primary);
  padding: var(--space-16) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--color-accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-banner h2 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-4);
  position: relative;
}

.cta-banner p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 1.125rem;
  margin-bottom: var(--space-8);
  position: relative;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-banner .btn {
  position: relative;
}

.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-10);
  margin-top: var(--space-12);
  flex-wrap: wrap;
}

.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.faq-item.active {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: all var(--transition-fast);
}

.faq-question:hover {
  background: var(--color-bg-alt);
}

.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all var(--transition-base);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-text-light);
}

.faq-item.active .faq-icon {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-text-inverse);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 var(--space-6) var(--space-5);
  font-size: 0.938rem;
  color: var(--color-text-light);
  line-height: 1.7;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-bg-dark);
  color: rgba(255, 255, 255, 0.7);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  margin-top: var(--space-4);
  max-width: 280px;
}

.footer-column h4 {
  color: var(--color-text-inverse);
  font-size: 0.813rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-5);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-links a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-inverse);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.813rem;
}

.footer-bottom-links {
  display: flex;
  gap: var(--space-6);
}

.footer-bottom-links a {
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition-fast);
}

.footer-bottom-links a:hover {
  color: var(--color-accent);
}

/* ===== Page-specific: Online Courses ===== */
.engagement-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.engagement-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.engagement-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.engagement-icon {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
  color: var(--color-primary);
}

.engagement-card h3 {
  margin-bottom: var(--space-3);
}

.engagement-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* Product Demo Accordion */
.product-demo-section {
  background: var(--color-bg-alt);
}

.demo-accordion {
  max-width: 900px;
  margin: 0 auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-card);
  overflow: hidden;
}

.demo-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) var(--space-8);
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--transition-fast);
}

.demo-trigger:hover {
  background: var(--color-bg-alt);
}

.demo-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  font-size: 1rem;
  flex-shrink: 0;
}

.demo-accordion.active .demo-icon {
  transform: rotate(45deg);
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-text-inverse);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.demo-accordion.active .demo-content {
  max-height: 600px;
}

.demo-content-inner {
  padding: 0 var(--space-8) var(--space-8);
}

.demo-mockup {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  border: 1px solid var(--color-border-light);
  min-height: 200px;
}

.demo-mockup-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.demo-mockup-col {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.demo-mockup-block {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-sm);
  padding: var(--space-3);
  font-size: 0.813rem;
  color: var(--color-text-light);
}

/* Tools Grid */
.tools-grid-large {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-4);
}

.tool-tag {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: var(--space-2) var(--space-4);
  font-size: 0.813rem;
  font-weight: 500;
  color: var(--color-text);
  text-align: center;
  transition: all var(--transition-fast);
  cursor: default;
}

.tool-tag:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-glow);
}

.tool-category {
  margin-bottom: var(--space-10);
}

.tool-category h3 {
  font-size: 0.938rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-light);
  margin-bottom: var(--space-4);
}

/* ===== Page-specific: Digital Downloads ===== */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.value-prop-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.value-prop-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.value-prop-icon {
  width: 56px;
  height: 56px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  font-size: 1.5rem;
  color: var(--color-primary);
}

.value-prop-card h3 {
  margin-bottom: var(--space-3);
}

.value-prop-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-4);
}

.file-type-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  text-align: center;
  transition: all var(--transition-fast);
}

.file-type-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.file-type-icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
}

.file-type-card h4 {
  font-size: 0.938rem;
}

/* Create & Sell Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.step-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  transition: all var(--transition-base);
}

.step-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.step-number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-4);
  opacity: 0.3;
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Memberships ===== */
.membership-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.benefit-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.benefit-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.benefit-stat {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-burgundy);
  line-height: 1;
  margin-bottom: var(--space-3);
}

.benefit-card h3 {
  margin-bottom: var(--space-3);
}

.benefit-card p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.resource-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  cursor: pointer;
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.resource-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: 1.25rem;
}

.resource-card h3 {
  font-size: 1.063rem;
  margin-bottom: var(--space-3);
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Page-specific: Coaching ===== */
.coaching-steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.coaching-step {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
  text-align: center;
  transition: all var(--transition-base);
}

.coaching-step:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.coaching-step-num {
  width: 48px;
  height: 48px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--color-primary);
  margin: 0 auto var(--space-5);
}

.coaching-step h3 {
  margin-bottom: var(--space-3);
}

.coaching-step p {
  font-size: 0.938rem;
  color: var(--color-text-light);
}

.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.coaching-feature-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  display: flex;
  gap: var(--space-5);
  transition: all var(--transition-base);
}

.coaching-feature-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
}

.coaching-feature-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.coaching-feature-text h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.coaching-feature-text p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.spotlight-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-avatar {
  width: 56px;
  height: 56px;
  background: var(--color-bg-alt);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-4);
}

.spotlight-card h3 {
  margin-bottom: var(--space-2);
  font-size: 1.125rem;
}

.spotlight-card p {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ===== Animations ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-content {
    order: 1;
  }

  .hero-visual {
    order: 0;
  }

  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

  .hero-tabs {
    margin-left: auto;
    margin-right: auto;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ai-features-grid {
    grid-template-columns: 1fr;
  }

  .scale-grid {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .pricing-card.featured:hover {
    transform: translateY(-4px);
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .coaching-features-grid {
    grid-template-columns: 1fr;
  }

  .spotlight-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .nav-links {
    display: none;
  }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--space-6);
    gap: var(--space-4);
    box-shadow: var(--shadow-lg);
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .engagement-grid,
  .value-props-grid,
  .membership-benefits-grid,
  .resources-grid,
  .coaching-steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }
}

@media (max-width: 768px) {
  .products-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .why-tabs-nav {
    gap: var(--space-4);
  }

  .section {
    padding: var(--space-12) 0;
  }

  .why-features-grid {
    grid-template-columns: 1fr;
  }

  .tools-grid-large {
    grid-template-columns: repeat(2, 1fr);
  }

  .file-types-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .carousel-btn {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}

/* ===== Utility ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.bg-alt { background: var(--color-bg-alt); }
.bg-dark { background: var(--color-bg-dark); }
.bg-primary { background: var(--color-primary); }

.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }

